<#
  Fix-RestoreNegotiateFeature.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  Restores the "Suggest a different price" negotiate button that
  Fix-RemoveNegotiateAndLiveJobs.ps1 removed a few sessions back. Nothing
  underlying was ever deleted when it was removed - the bid database
  table, the accept_bid RPC, and dashboard\page.jsx's counterOffer()
  handler were all left in place on purpose, specifically so this would
  be a clean, safe restoration rather than rebuilding from scratch.

  What comes back, in src\components\rider\IncomingOrderCard.jsx:
    - The "Suggest a different price" button and its amount input,
      alongside Accept Signal (not replacing it).
    - Every bid still rounds UP to the nearest ₦50 before it's sendable
      (₦2020 or ₦2034 both become ₦2050), with a live "this sends as
      ₦X" preview if what's typed isn't already round.
    - Once a bid is pending, the card shows a "waiting for vendor" state
      with a fallback to just accept the base price instead, rather than
      letting a rider send a second, conflicting bid.

  src\app\rider\(main)\dashboard\page.jsx: reconfirmed - no changes
  needed here, counterOffer() and the onCounterOffer wiring were already
  intact and unreachable, exactly as designed. Included in this script
  anyway so both files are guaranteed to match and nothing is left
  half-applied.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  every existing file it touches to .fix-backup-restore-negotiate\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-RestoreNegotiateFeature.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-restore-negotiate"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Force -Path $targetParent | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nRestoring the negotiate feature:" -ForegroundColor Cyan

$b64_BIDCARD = ""
Write-FileFromBase64 "src\components\rider\IncomingOrderCard.jsx" $b64_BIDCARD

$b64_DASHBOARD = ""
Write-FileFromBase64 "src\app\rider\(main)\dashboard\page.jsx" $b64_DASHBOARD

Write-Host "`nDone. Backups saved under .fix-backup-restore-negotiate\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then commit, push, and redeploy." -ForegroundColor Cyan
